timeout 1800 omp -p --auto-approve --mode json --model neuralwatt/deepseek-v4-flash "$(cat /work/PROMPT.txt)" < /dev/null > /work/transcript.jsonl 2> /work/probe-stderr.log
rc=$?; echo probe-exit=$rc; exit $rc


